package app.streamnest;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;import java.util.*;
public class ManualWatchedTest {
 Catalog.Title t(String id,String kind,String genre)throws Exception{return Catalog.parse(new JSONObject().put("imdb",id).put("title",id).put("genres",new JSONArray().put(genre)),kind);}
 JSONObject row(boolean watched,long at)throws Exception{return new JSONObject().put("watched",watched).put("updatedAt",at).put("title",HomeSync.metadata(t("tt1","shows","action").raw,"shows"));}
 @Test public void manualPicksAreIndependentOfResumeAndUndoWins()throws Exception{List<Catalog.Title> pool=Arrays.asList(t("tt1","shows","action"),t("tt2","movies","action"),t("tt3","movies","drama"));JSONObject yes=new JSONObject().put("tt1",row(true,100)),no=new JSONObject().put("tt1",row(false,200));List<HomeFeed.Row> rows=HomeFeed.build(pool,new JSONObject(),12,yes);assertTrue(rows.get(0).cards.isEmpty());assertEquals("tt2",rows.get(1).cards.get(0).title.id);for(HomeFeed.Row r:rows)for(HomeFeed.Card c:r.cards)assertNotEquals("tt1",c.title.id);assertFalse(ManualWatched.merge(no,yes).getJSONObject("tt1").getBoolean("watched"));JSONObject home=HomeSync.create(pool,new JSONObject(),null,System.currentTimeMillis(),yes);assertEquals(ManualWatched.signature(yes),home.getString("manual"));assertFalse(home.getJSONObject("watched").has("tt1"));}
 @Test public void namespaceAndTombstoneTieAreStable()throws Exception{String code=WatchSyncCrypto.create(),derived=WatchSyncCrypto.manualCode(code);assertNotEquals(WatchSyncCrypto.homeCode(code),derived);JSONObject rows=new JSONObject().put("tt1",row(true,100)),undo=new JSONObject().put("tt1",row(false,100));assertFalse(ManualWatched.merge(rows,undo).getJSONObject("tt1").getBoolean("watched"));assertFalse(ManualWatched.merge(undo,rows).getJSONObject("tt1").getBoolean("watched"));assertEquals(0,WatchSyncCrypto.open(derived,WatchSyncCrypto.seal(derived,rows)).length());}
 @Test public void desktopCipherAndDigestMatchAndroid()throws Exception{JSONObject f;try(java.io.InputStream in=getClass().getResourceAsStream("/manual-watched-vector.json")){f=new JSONObject(new String(in.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8));}assertEquals(f.getString("derived"),WatchSyncCrypto.manualCode(f.getString("code")));JSONObject rows=WatchSyncCrypto.openDocument(f.getString("derived"),f.getJSONObject("encrypted"));assertEquals(f.getString("signature"),ManualWatched.signature(rows));assertTrue(rows.getJSONObject("tt99003001").getBoolean("watched"));}
 @Test public void shutdownGuardAcceptsOnlyPinnedLibraryNullSessionRace(){NullPointerException race=new NullPointerException("session.pop_alerts on null");race.setStackTrace(new StackTraceElement[]{new StackTraceElement("org.libtorrent4j.SessionManager$5","run","SessionManager.java",1168)});assertTrue(EngineStartup.shutdownRace(race));assertFalse(EngineStartup.shutdownRace(new NullPointerException("unrelated")));assertFalse(EngineStartup.shutdownRace(new IllegalStateException("pop_alerts")));}
 @Test public void watchdogBlocksReplacementUntilNativeCallDrains()throws Exception{long[] now={0};EngineStartup s=new EngineStartup(()->now[0]);s.begin("Stopping previous session",20000);now[0]=21000000000L;assertTrue(s.expired());assertTrue(s.active);assertTrue(s.status().contains("Startup stalled"));try{s.check();fail();}catch(java.io.IOException expected){}s.done();assertFalse(s.active);s.begin("Checking cache folder",20000);assertFalse(s.expired());s.check();}
}
